/* The caller supplies count live long elements; count zero uses no element. */
void menu_sort(long *values, size_t count) {
    for (size_t i = 1; i < count; ++i) {
        long key = values[i];
        size_t j = i;
        while (j > 0 && values[j - 1] > key) {
            values[j] = values[j - 1];
            --j;
        }
        values[j] = key;
    }
}
int menu_run(FILE *input, FILE *output) {
