    snprintf(expected_text, sizeof expected_text, "63 bytes, 1 words\n%s | checked\n", exact);
    console_case(1, exact, 0, expected_text);
    const long unsorted[][8] = {{3, 2, 1, 0, -1, -2, -3, -4}, {-4, -3, -2, -1, 0, 1, 2, 3}, {2, 2, -1, 0, 2, -1, 0, 0}};
