    for (size_t row = 0; row < 3; ++row) {
        long data[8]; memcpy(data, unsorted[row], sizeof data); menu_sort(data, 8);
        for (size_t i = 0; i < 8; ++i) test(data[i] == sorted[row][i], "sort order and multiset");
    }
    menu_sort(NULL, 0);
    long single = 7; menu_sort(&single, 1); test(single == 7, "empty/single sort");
    console_case(2, "", 0, "");
    console_case(2, "p\ns\np\nq\n", 0, "Values:\nValues:\n");
    console_case(2, "a\n3\na\n-2\na\n3\ns\np\nq\n", 0, "Values: -2 3 3\n");
    console_case(2, "a\n-1000\na\n1000\np", 0, "Values: -1000 1000\n");
    console_case(2, "x\n", 1, "Unknown command\n");
    console_case(2, "\n", 1, "Use one command: a, p, s, q\n");
    console_case(2, "q extra\n", 1, "Use one command: a, p, s, q\n");
    for (size_t i = 0; i < sizeof invalid / sizeof invalid[0]; ++i) {
        char command[128]; snprintf(command, sizeof command, "a\n%s\n", invalid[i]);
        console_case(2, command, 1, "Invalid value\n");
    }
    console_case(2, "a\n", 1, "Invalid value\n");
    console_case(2, "a\n1\na\n2\na\n3\na\n4\na\n5\na\n6\na\n7\na\n8\np\na\n9\n", 1, "Values: 1 2 3 4 5 6 7 8\nFull\n");
    printf("%u scenario checks passed\n", scenario_checks);
    return 0;
}

