static int checks;
static void test(int condition) { if(!condition) { fputs("sum mismatch\n", stderr); return; } ++checks; }
int main(void) {
    long out = 77;
    int values[101];
    for (size_t i = 0; i < 101; ++i) values[i] = 1000;
    test(checked_sum(values, 100, &out) && out == 100000);
    out = 77;
    test(!checked_sum(values, 101, &out) && out == 77);
    values[99] = 1001;
    test(!checked_sum(values, 100, &out) && out == 77);
    values[99] = -1001;
    test(!checked_sum(values, 100, &out) && out == 77);
    test(!checked_sum(NULL, 1, &out) && out == 77);
    test(!checked_sum(values, 1, NULL));
    test(checked_sum(NULL, 0, &out) && out == 0);
    values[0] = -1000;
    test(checked_sum(values, 1, &out) && out == -1000);
    test(checked_sum(values, 0, &out) && out == 0);
    printf("%d sum boundary checks passed\n", checks);
    return checks == 9 ? 0 : 1;
}
